async function run(ctx) {
  const question = ctx.trigger.payload.question || "Introduce yourself in one sentence";
  ctx.tools.log("question:", question);
  const r = await ctx.tools.exec(
    `claude -p ${JSON.stringify(question + " (answer concisely)")}`,
    { timeoutMs: 150000 }
  );
  if (r.exitCode !== 0) { ctx.tools.fail("claude call failed: " + r.stderr.slice(0, 200)); }
  return { question: question, answer: r.stdout.trim() };
}
